    [4443]={name="Grim Pauldrons",sourceType="quest_reward",instructions="Reward from the quest “To Steal From Thieves” — pick it over the other choices. In Undercity.",zone="Undercity",questName="To Steal From Thieves",lore="The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed! My family is gone, taken by the plague."},
