    [12465]={name="Nightfall Drape",sourceType="boss_drop",instructions="Drops from Morphaz in Sunken Temple.",zone="Sunken Temple",npc="Morphaz"},
    [12546]={name="Aristocratic Cuffs",sourceType="world_drop",instructions="World drop — drops from 50 creature types around level 48-56. Also found on the auction house."},
    [12547]={name="Mar Alom's Grip",sourceType="world_drop",instructions="World drop — drops from 50 creature types around level 48-56. Also found on the auction house."},
    [12548]={name="Magni's Will",sourceType="quest_reward",instructions="Reward from the quest “The Princess's Surprise” — pick it over the other choices. In Blackrock Depths.",zone="Blackrock Depths",questName="The Princess's Surprise",lore="Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child! Return to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf."},
    [12550]={name="Runed Golem Shackles",sourceType="world_drop",instructions="World drop — drops from 50 creature types around level 48-56. Also found on the auction house."},
