    [12633]={name="Whitesoul Helm",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [12637]={name="Backusarian Gauntlets",sourceType="boss_drop",instructions="Drops from Bannok Grimaxe in Blackrock Spire.",zone="Blackrock Spire",npc="Bannok Grimaxe"},
    [12639]={name="Stronghold Gauntlets",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing"},
    [12640]={name="Lionheart Helm",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing",lore="A crafted helm that outlived several tiers of raid gear. Its plans were the thing guilds actually fought over."},
    [12790]={name="Arcanite Champion",sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 1).",profession="Blacksmithing",proc="Chance on hit: Heal self for 270 to 450 and increases Strength by 120 for 30 sec."},
    [12895]={name="Breastplate of the Chromatic Flight",sourceType="quest_reward",instructions="Reward from the quest “Breastplate of the Chromatic Flight”. In Western Plaguelands.",zone="Western Plaguelands",questName="Breastplate of the Chromatic Flight",lore="The forging of a powerful breastplate to protect against the unrelenting attacks of the chromatic flight is one built upon irony."},
    [12927]={name="Truestrike Shoulders",sourceType="boss_drop",instructions="Drops from Pyroguard Emberseer in Blackrock Spire.",zone="Blackrock Spire",npc="Pyroguard Emberseer"},
